/bin/bash -lc "python3 - <<'PY'
import pathlib
import subprocess
import tempfile

repo = pathlib.Path.cwd()
before = {str(p.relative_to(repo)): p.read_bytes() for p in repo.rglob('*') if p.is_file() and '.git' not in p.relative_to(repo).parts}
with tempfile.TemporaryDirectory(prefix='parse-port-check-') as directory:
    work = pathlib.Path(directory)
    for name in ('check.cpp', 'app.hpp', 'service.hpp'):
        (work / name).symlink_to(repo / name)
    subprocess.run(['python3', str(repo / 'check.py')], cwd=work, check=True)
    print('Supplied check.py: PASS', flush=True)
    source = r'''
#include \"service.hpp\"
#include <cassert>
#include <string>
int main() {
    for (int port = 1; port <= 65535; ++port) {
        assert(parsePort(std::to_string(port)) == port);
        assert(parsePort(\"000\" + std::to_string(port)) == port);
    }
    for (const auto& s : {\"\", \"0\", \"000\", \"65536\", \"655350\", \"+1\", \"-1\", \" 1\", \"1 \", \"1\\n\", \"1.0\", \"1x\", \"2147483647\", \"2147483648\", \"4294967296\"})
        assert(parsePort(s) == -1);
    assert(parsePort(std::string(\"12\\0\" \"3\", 4)) == -1);
    assert(parsePort(std::string(10000, '9')) == -1);
    assert(parsePort(std::string(10000, '0') + \"65535\") == 65535);
    for (int byte = 0; byte <= 255; ++byte) {
        if (byte < '0' || byte > '9')
            assert(parsePort(std::string(\"1\") + static_cast<char>(byte)) == -1);
    }
}
'''
    executable = work / 'edge-check'
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-fsanitize=undefined', '-fno-sanitize-recover=all', '-I', str(repo), '-x', 'c++', '-', '-o', str(executable)], input=source, text=True, check=True)
    subprocess.run([str(executable)], check=True)
    print('Exhaustive valid ports and malformed/overflow edge checks: PASS')
after = {str(p.relative_to(repo)): p.read_bytes() for p in repo.rglob('*') if p.is_file() and '.git' not in p.relative_to(repo).parts}
assert before == after, 'Verification altered repository files'
print('Verification left repository files unchanged.')
PY"

